negativeExample:
import org.junit.Assert;
import org.junit.Test;

class MyTestException extends Exception {}

class MyService {
    public void performAction() throws MyTestException {
        // complex logic
    }
    public void performActionWithArg(String arg) throws MyTestException {
        if (arg == null) {
            throw new MyTestException();
        }
    }
    public String getString() { return "test"; }
}

public class NegativeExampleTest {
    @Test
    public void testWithArgLambda() {
        MyService service = new MyService();
        // Should not match: lambda calls a method with arguments
        Assert.assertThrows(MyTestException.class, () -> service.performActionWithArg(service.getString()));
    }

    @Test
    public void testComplexLambda() {
        MyService service = new MyService();
        // Should not match: lambda has a complex body, not just a simple method call
        Assert.assertThrows(MyTestException.class, () -> {
            System.out.println("Calling action...");
            service.performAction();
        });
    }
}
